// Radar Normativo Bolivia — detecta normas nuevas del SIN y evita repetir avisos.
// Estructura HTML verificada con curl el 2026-07-04 (runbook: ONIA_RADAR_NORMATIVO_RUNBOOK_2026.md):
// - impuestos.com.bo/normativa-<anio>/ (WordPress estatico, scrapeable): cada norma es
//   <h2 class="wp-block-heading"><span class="ez-toc-section" id="RND-..."></span>
//   <a href="https://www.impuestos.gob.bo/....pdf">RND-102600000012</a><span class="ez-toc-section-end"></span></h2>
//   seguida de <p class="wp-block-paragraph">resumen</p> (los decretos supremos se mencionan en ese resumen).
// - siatinfo.impuestos.gob.bo (Joomla estatico, scrapeable): anchors <a href="....pdf">RND-102500000018</a>.
const ZONA = 'America/La_Paz';
const ahora = new Date();
const anio = new Intl.DateTimeFormat('es-BO', { timeZone: ZONA, year: 'numeric' }).format(ahora);
const anio2 = anio.slice(2);

const limpiar = (s) => String(s).replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&#160;/g, ' ').replace(/&amp;/g, '&').replace(/\s+/g, ' ').trim();

const htmlDe = (nombre) => {
  try {
    const j = $(nombre).first().json;
    return String(j.data ?? '');
  } catch (e) {
    return '';
  }
};

const items = [];
let m;

// Fuente 1: pagina de normativa del anio en curso (impuestos.com.bo).
const htmlNormativa = htmlDe('Normativa SIN (impuestos.com.bo)');
const RE_WP = /<h2 class="wp-block-heading"><span class="ez-toc-section" id="[^"]*"><\/span><a href="([^"]+)"[^>]*>\s*([^<]{3,80}?)\s*<\/a><span class="ez-toc-section-end"><\/span><\/h2>\s*(?:<p[^>]*>([\s\S]{0,400}?)<\/p>)?/g;
while ((m = RE_WP.exec(htmlNormativa)) !== null) {
  items.push({ titulo: limpiar(m[2]).toUpperCase(), link: m[1], resumen: limpiar(m[3] || '').slice(0, 160), fuente: 'impuestos.com.bo' });
}

// Fuente 2: home de siatinfo (novedades oficiales de facturacion).
const htmlSiat = htmlDe('SIAT novedades (siatinfo)');
const RE_SIAT = /<a href="([^"]+)"[^>]*>\s*(RND[-\s]?N?°?\s?\d{10,14})\s*<\/a>/gi;
while ((m = RE_SIAT.exec(htmlSiat)) !== null) {
  const link = m[1].indexOf('http') === 0 ? m[1] : 'https://siatinfo.impuestos.gob.bo' + m[1];
  items.push({ titulo: limpiar(m[2]).toUpperCase(), link, resumen: '', fuente: 'siatinfo (SIN)' });
}

// Solo lo del anio en curso: el codigo RND embebe el anio (10YY), o el titulo/link lo menciona.
const RE_ANIO = new RegExp('RND[-\\s]?N?°?\\s?10' + anio2 + '\\d');
const esDelAnio = (it) => it.titulo.includes(anio) || RE_ANIO.test(it.titulo) || it.link.includes('/' + anio + '/');

const enCorrida = new Set();
const delAnio = items.filter((it) => {
  if (!esDelAnio(it) || enCorrida.has(it.titulo)) return false;
  enCorrida.add(it.titulo);
  return true;
});

// Memoria entre ejecuciones: solo persiste en ejecuciones de produccion (workflow activo), no en Test.
const memoria = $getWorkflowStaticData('global');
if (!Array.isArray(memoria.lastSeen)) memoria.lastSeen = [];
const yaVistos = new Set(memoria.lastSeen);
const novedades = delAnio.filter((it) => !yaVistos.has(it.titulo));
memoria.lastSeen = memoria.lastSeen.concat(novedades.map((it) => it.titulo)).slice(-200); // cap 200, FIFO

const fecha = new Intl.DateTimeFormat('es-BO', { timeZone: ZONA, day: '2-digit', month: '2-digit', year: 'numeric' }).format(ahora);
const MAX_LISTA = 15; // limite defensivo (Telegram corta a 4096 chars)
const visibles = novedades.slice(0, MAX_LISTA);
const lineas = [
  'Radar Normativo Bolivia — ' + fecha,
  '',
  ...visibles.map((it) => '• ' + it.titulo + ' [' + it.fuente + ']' + (it.resumen ? '\n  ' + it.resumen : '') + '\n  ' + it.link),
  novedades.length > MAX_LISTA ? '(+' + (novedades.length - MAX_LISTA) + ' mas en las fuentes)' : null,
  '',
  'Revisar impacto en clientes → crear pendiente si aplica.',
].filter((l) => l !== null);

return [{
  json: {
    count: novedades.length,
    novedades,
    text: lineas.join('\n'),
    anio,
    fuentesLeidas: { normativa: htmlNormativa.length > 0, siatinfo: htmlSiat.length > 0 },
  },
}];
